 "content": "from collections import deque


def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x, color))
                for ny, nx in ((y-1, x), (y+1, x), (y, x-1), (y, x+1)):
                    if 0 <= ny < h and 0 <= nx < w and (ny, nx) not in seen and grid[ny][nx] == color:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            objects.append(cells)

    # Pack each rigid component to the right, resolving rightmost components first.
    objects.sort(key=lambda obj: max(c for _, c, _ in obj), reverse=True)
    result = [[0] * w for _ in range(h)]
    for obj in objects:
        dr = 0
        while True:
            shift = dr + 1
            if any(c + shift >= w or result[r][c + shift] != 0 for r, c, _ in obj):
                break
            dr = shift
        for r, c, color in obj:
            result[r][c + dr] = color
    return result
